import { useEffect, useState } from 'react'

export function useTokenListWorker() {
  const [data, setData] = useState([])

  useEffect(() => {
    const worker = new Worker('/worker/tokenlist.js')
    console.log('🚀 ~ file: useTokenListWorker.ts:8 ~ useEffect ~ worker:', worker)
    worker.postMessage({
      url: 'https://api-sui.cetus.zone/v2/sui/stats_pools?is_vaults=false&display_all_pools=false&has_mining=true&has_farming=true&no_incentives=true&order_by=-vol&limit=30&offset=0', // 替换为你的接口地址
      interval: 5000 // 轮询间隔，单位为毫秒
    })

    worker.onmessage = event => {
      if (event.data.error) {
        console.log('🚀 ~ file: useTokenListWorker.ts:15 ~ useEffect ~ event.data.error:', event.data.error)
      } else {
        console.log('🚀 ~ file: useTokenListWorker.ts:15 ~ useEffect ~ event.data:', event.data)
        setData(event.data)
      }
    }

    return () => {
      worker.terminate() // 清理 Web Worker
    }
  }, [])
}
